class Carousel{constructor(images,options={}){this.images=images;this.currentIndex=0;this.options={autoPlay: options.autoPlay||false,autoPlayInterval: options.autoPlayInterval||3000,loop: options.loop!==undefined ? options.loop : true,transitionDuration: options.transitionDuration||300,...options};this.autoPlayTimer=null;this.isTransitioning=false;this.mainImageElement=null;this.thumbnailElements=[];this.prevButton=null;this.nextButton=null;}setElements(mainImageElement,thumbnailElements=[],prevButton=null,nextButton=null){this.mainImageElement=mainImageElement;this.thumbnailElements=thumbnailElements;this.prevButton=prevButton;this.nextButton=nextButton;this.setupEventListeners();this.updateDisplay();}setupEventListeners(){if(this.prevButton){this.prevButton.addEventListener('click',()=>this.previous());}if(this.nextButton){this.nextButton.addEventListener('click',()=>this.next());}this.thumbnailElements.forEach((thumbnail,index)=>{thumbnail.addEventListener('click',()=>this.goto(index));});document.addEventListener('keydown',(e)=>{if(e.key==='ArrowLeft')this.previous();if(e.key==='ArrowRight')this.next();});}next(){if(this.isTransitioning)return;if(this.currentIndex<this.images.length-1){this.goto(this.currentIndex+1);}else if(this.options.loop){this.goto(0);}}previous(){if(this.isTransitioning)return;if(this.currentIndex>0){this.goto(this.currentIndex-1);}else if(this.options.loop){this.goto(this.images.length-1);}}goto(index){if(this.isTransitioning)return;if(index<0||index>=this.images.length)return;if(index===this.currentIndex)return;this.currentIndex=index;this.updateDisplay();if(this.options.autoPlay){this.resetAutoPlay();}}updateDisplay(){if(!this.mainImageElement)return;this.isTransitioning=true;this.mainImageElement.classList.add('carousel-transitioning');setTimeout(()=>{this.mainImageElement.src=this.images[this.currentIndex];this.updateThumbnails();setTimeout(()=>{this.mainImageElement.classList.remove('carousel-transitioning');this.isTransitioning=false;},this.options.transitionDuration);},this.options.transitionDuration/2);}updateThumbnails(){this.thumbnailElements.forEach((thumbnail,index)=>{if(index===this.currentIndex){thumbnail.classList.add('active');}else{thumbnail.classList.remove('active');}});}getCurrentIndex(){return this.currentIndex;}getCurrentImage(){return this.images[this.currentIndex];}startAutoPlay(){if(!this.options.autoPlay)return;this.autoPlayTimer=setInterval(()=>{this.next();},this.options.autoPlayInterval);}stopAutoPlay(){if(this.autoPlayTimer){clearInterval(this.autoPlayTimer);this.autoPlayTimer=null;}}resetAutoPlay(){this.stopAutoPlay();this.startAutoPlay();}destroy(){this.stopAutoPlay();}}function initializeCarousels(){const carouselContainers=document.querySelectorAll('[data-carousel]');carouselContainers.forEach(container=>{const mainImage=container.querySelector('[data-carousel-main]');const thumbnails=Array.from(container.querySelectorAll('[data-carousel-thumbnail]'));const prevButton=container.querySelector('[data-carousel-prev]');const nextButton=container.querySelector('[data-carousel-next]');const images=thumbnails.map(thumb=>thumb.dataset.image||thumb.src);const carousel=new Carousel(images,{autoPlay: container.dataset.autoplay==='true',loop: container.dataset.loop!=='false'});carousel.setElements(mainImage,thumbnails,prevButton,nextButton);if(carousel.options.autoPlay){carousel.startAutoPlay();container.addEventListener('mouseenter',()=>carousel.stopAutoPlay());container.addEventListener('mouseleave',()=>carousel.startAutoPlay());}});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initializeCarousels);}else{initializeCarousels();}function initializeV2Carousel(){const carouselV2=document.querySelector('[data-carousel-v2]');if(!carouselV2)return;const slides=Array.from(carouselV2.querySelectorAll('.image-slide'));const navDots=Array.from(document.querySelectorAll('.nav-dot'));let currentSlide=0;let isTransitioning=false;function showSlide(index,smooth=true){if(isTransitioning)return;if(index<0||index>=slides.length)return;if(index===currentSlide)return;isTransitioning=true;slides.forEach(slide=>slide.classList.remove('active'));navDots.forEach(dot=>dot.classList.remove('active'));if(slides[index]){slides[index].classList.add('active');}if(navDots[index]){navDots[index].classList.add('active');}currentSlide=index;setTimeout(()=>{isTransitioning=false;},600);}navDots.forEach((dot,index)=>{dot.addEventListener('click',()=>{showSlide(index);});});document.addEventListener('keydown',(e)=>{if(e.key==='ArrowUp'&&currentSlide>0){e.preventDefault();showSlide(currentSlide-1);}else if(e.key==='ArrowDown'&&currentSlide<slides.length-1){e.preventDefault();showSlide(currentSlide+1);}});const galleryPanel=document.querySelector('.gallery-panel');if(galleryPanel){let wheelTimeout;galleryPanel.addEventListener('wheel',(e)=>{e.preventDefault();clearTimeout(wheelTimeout);wheelTimeout=setTimeout(()=>{if(e.deltaY>0&&currentSlide<slides.length-1){showSlide(currentSlide+1);}else if(e.deltaY<0&&currentSlide>0){showSlide(currentSlide-1);}},50);},{passive: false});}let touchStartY=0;let touchEndY=0;carouselV2.addEventListener('touchstart',(e)=>{touchStartY=e.changedTouches[0].screenY;});carouselV2.addEventListener('touchend',(e)=>{touchEndY=e.changedTouches[0].screenY;handleSwipe();});function handleSwipe(){const swipeThreshold=50;if(touchStartY-touchEndY>swipeThreshold&&currentSlide<slides.length-1){showSlide(currentSlide+1);}else if(touchEndY-touchStartY>swipeThreshold&&currentSlide>0){showSlide(currentSlide-1);}}initializeCustomerPhotoCarousel();}function initializeCustomerPhotoCarousel(){const photosScroll=document.querySelector('.photos-scroll');if(!photosScroll)return;const customerThumbs=Array.from(photosScroll.querySelectorAll('.customer-thumb'));customerThumbs.forEach((thumb,index)=>{thumb.addEventListener('click',()=>{thumb.style.transform='scale(1.1)';setTimeout(()=>{thumb.style.transform='';},200);});});let scrollPosition=0;let scrollDirection=1;let autoScrollInterval;function startAutoScroll(){autoScrollInterval=setInterval(()=>{const maxScroll=photosScroll.scrollWidth-photosScroll.clientWidth;scrollPosition+=scrollDirection*1;if(scrollPosition>=maxScroll){scrollDirection=-1;}else if(scrollPosition<=0){scrollDirection=1;}photosScroll.scrollLeft=scrollPosition;},30);}function stopAutoScroll(){if(autoScrollInterval){clearInterval(autoScrollInterval);autoScrollInterval=null;}}photosScroll.addEventListener('mouseenter',stopAutoScroll);photosScroll.addEventListener('mouseleave',startAutoScroll);photosScroll.addEventListener('scroll',()=>{scrollPosition=photosScroll.scrollLeft;});setTimeout(startAutoScroll,2000);}function initializeReviewCarousel(){const reviewCarousel=document.querySelector('[data-review-carousel]');if(!reviewCarousel)return;const track=reviewCarousel.querySelector('.carousel-track');const cards=Array.from(track.querySelectorAll('.review-card-carousel'));const prevButton=reviewCarousel.querySelector('.carousel-prev');const nextButton=reviewCarousel.querySelector('.carousel-next');const indicators=Array.from(reviewCarousel.parentElement.querySelectorAll('.indicator'));let currentIndex=0;let autoScrollTimer=null;const autoScrollInterval=5000;function updateCarousel(){const cardWidth=cards[0].offsetWidth;const gap=20;const offset=-(currentIndex*(cardWidth+gap));track.style.transform=`translateX(${offset}px)`;indicators.forEach((indicator,index)=>{if(index===currentIndex){indicator.classList.add('active');}else{indicator.classList.remove('active');}});if(prevButton){prevButton.disabled=currentIndex===0;}if(nextButton){nextButton.disabled=currentIndex===cards.length-1;}}function nextSlide(){if(currentIndex<cards.length-1){currentIndex++;updateCarousel();}}function prevSlide(){if(currentIndex>0){currentIndex--;updateCarousel();}}function startAutoScroll(){autoScrollTimer=setInterval(()=>{if(currentIndex<cards.length-1){nextSlide();}else{currentIndex=0;updateCarousel();}},autoScrollInterval);}function stopAutoScroll(){if(autoScrollTimer){clearInterval(autoScrollTimer);autoScrollTimer=null;}}function resetAutoScroll(){stopAutoScroll();startAutoScroll();}if(prevButton){prevButton.addEventListener('click',()=>{prevSlide();resetAutoScroll();});}if(nextButton){nextButton.addEventListener('click',()=>{nextSlide();resetAutoScroll();});}reviewCarousel.addEventListener('mouseenter',stopAutoScroll);reviewCarousel.addEventListener('mouseleave',startAutoScroll);let touchStartX=0;let touchEndX=0;reviewCarousel.addEventListener('touchstart',(e)=>{touchStartX=e.changedTouches[0].screenX;stopAutoScroll();});reviewCarousel.addEventListener('touchend',(e)=>{touchEndX=e.changedTouches[0].screenX;handleSwipe();startAutoScroll();});function handleSwipe(){const swipeThreshold=50;if(touchStartX-touchEndX>swipeThreshold){nextSlide();}else if(touchEndX-touchStartX>swipeThreshold){prevSlide();}}updateCarousel();startAutoScroll();}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>{initializeV2Carousel();initializeReviewCarousel();});}else{initializeV2Carousel();initializeReviewCarousel();}